def IM(name, h=190): return FIG(name).replace('<img class="fig"', f'<img style="height: {h}px; border-radius: 12px; border: 3px solid #D5DEEA; vertical-align: middle; margin-inline-start: 24px"')
def SV(svg, h=300): return svg.replace('<svg class="svgfig', f'<svg style="height: {h}px; width: auto; vertical-align: middle" class="svgfig')
def K(t): return f'<b style="color: #C2410C">{t}</b>'
def KF(n, d): return K(FR(n, d))
def MX(w, n, d): return f'<span style="display: inline-flex; align-items: center; gap: .12em; direction: rtl; unicode-bidi: isolate">{w}{FR(n, d)}</span>'   # العدد الكامل يمين الكسر
def KM(w, n, d): return K(MX(w, n, d))
def WH(den, num, color='#F59E0B', h=90, rows=1):   # مستطيلاتٌ متطابقة كلٌّ منها واحدٌ صحيح، يبدأ التظليل من المستطيل الأيمن
    k = -(-num // den)
    return '<span style="display: inline-flex; gap: 22px; align-items: center; direction: rtl">' + ''.join(SV(FBAR(den, min(den, num - i * den), rows=rows, color=color, label=False, w=300), h) for i in range(k)) + '</span>'
